def lightestCycle(n, edges):
    INF = 10 ** 15
    w = [[INF] * n for _ in range(n)]
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for a, b, c in edges:
        w[a][b] = w[b][a] = c
        d[a][b] = d[b][a] = c
    best = INF
    for k in range(n):
        wk = w[k]
        nbrs = [i for i in range(k) if wk[i] < INF]
        for x in range(len(nbrs)):
            i = nbrs[x]
            di = d[i]
            for y in range(x):
                j = nbrs[y]
                s = di[j] + wk[i] + wk[j]
                if s < best:
                    best = s
        dk = d[k]
        for i in range(n):
            dik = d[i][k]
            if dik < INF:
                d[i] = [p if p <= dik + q else dik + q for p, q in zip(d[i], dk)]
    return -1 if best >= INF else best
